import type { TraceStep } from '../domain/evaluation/types'

interface CalculationTraceProps {
  /** The steps, as `calculationTrace` produced them from an evaluation result. */
  steps: readonly TraceStep[]
}

/**
 * The calculation trace: the ten steps of the evaluation, always in the same order.
 *
 * This is a record of what the arithmetic did, not an explanation of it — the same observation
 * always produces the same ten lines, and a step that could not be completed says so instead of
 * being left out. Nothing here is generated by anything other than `calculationTrace` in the domain
 * layer; this component only renders the steps it is given.
 *
 * It renders the list and nothing else: the title and the "n of 10 steps completed" line belong to
 * whatever presents it — a disclosure on the test screen, a subsection of the printed document — so
 * that the same ten steps are never headed two different ways.
 */
export function CalculationTrace({ steps }: CalculationTraceProps) {
  return (
    <ol className="trace">
      {steps.map((step) => (
        <li key={step.step} className={step.completed ? 'trace-step' : 'trace-step incomplete'}>
          <span className="trace-index">{step.step}</span>
          <span className="trace-label">{step.label}</span>
          <span className="trace-value">{step.value}</span>
          {step.clause ? <span className="trace-clause">{step.clause}</span> : null}
        </li>
      ))}
    </ol>
  )
}
